import React, { useEffect } from 'react';
import { useLocation } from 'react-router-dom';
import BookForm from '../../features/books/BookForm';
import BookList from '../../features/books/BookList';

export default function BooksManagement({ locationState }) {
  const refetchRef = React.useRef(null);

  return (
    <div className="books-management">
      <h1>Books Management</h1>
      <BookForm onBookCreated={(count = 1) => { if (refetchRef.current) refetchRef.current(); }} />
      <BookList setRefetch={(refetch) => { refetchRef.current = refetch; }} />
    </div>
  );
}
